item.aggregated_output:
                session_id=session_id,
            )
        if state.run_id != self.server_run.run_id:
            self._invalidate_locked(key, "plan belongs to a different Server Run")
            raise _refuse(
                "plan/run-mismatch",
                "The active plan belongs to a different Server Run; submit a new plan.",
                session_id=session_id,
            )
        if invoked_action == definition.action_name:
            action_remaining = state.remaining_calls
        elif invoked_action in definition.paired_actions:
            action_remaining = state.paired_remaining.get(invoked_action, 0)
        else:  # pragma: no cover - definition lookup already constrains this branch
            action_remaining = 0
        if action_remaining <= 0:
            raise _refuse(
                "plan/action-exhausted",
                f"Plan {state.plan_id} has no remaining {invoked_action} allowance; submit a "
                "replacement plan if more work is required.",
                session_id=session_id,
            )
        if state.session_id != session_id:
            self._invalidate_locked(key, "session changed")
            raise _refuse(
                "plan/session-mismatch",
                "The board session changed; the plan was invalidated and must be replaced.",
                session_id=session_id,
            )
        lock_name = (
            invoked_action
            if self.registry.is_registered(invoked_action)
            else definition.action_name
        )
        if not self.registry.is_unlocked(lock_name, key[1]):
            raise _refuse(
                "plan/tool-locked",
                f"{invoked_action} is physically locked; call {definition.plan_tool_name} again.",
                session_id=session_id,
            )
        return state

    def complete_paired_plan(self, action_name: str, board_id: str, reason: str) -> None:
        """Close a paired workflow early and consume any one-time authorization.

        Setup calls this when it completes, is cancelled, or reaches a terminal
        stop before both statically granted calls are used. Full-session grants
        remain reusable because their provider consumption is intentionally a no-op.
        """

        definition = _definition(action_name)
        key = (definition.action_name, board_id)
        with self._guard:
            state = self.server_run.plans.get(key)
            if not isinstance(state, _PlanState) or state.status is not PlanStatus.ACTIVE:
                return
            authorization = state.authorization
        if definition.permission_mode is not PermissionMode.NONE and authorization is not None:
            try:
                self.permission_provider.consume_execution(
                    definition,
                    board_id,
                    authorization,
                )
            except PolicyRefusal:
                # Revocation may already have removed the grant; closure still relocks.
                pass
        with self._guard:
            self._invalidate_locked(key, reason)

    def active_plan(self, action_name: str, board_id: str) -> ActivePlan | None:
        definition = _definition(action_name)
        key = (definition.action_name, board_id)
        with self._guard:
            state = self.server_run.plans.get(key)
            if not isinstance(state, _PlanState) or state.status is not PlanStatus.ACTIVE:
                return None
            return state.snapshot()

    def invalidate(self, action_name: str, board_id: str, reason: str) -> None:
        definition = _definition(action_name)
        with self._guard:
            self._invalidate_locked((definition.action_name, board_id), reason)

    def invalidate_board(self, board_id: str, reason: str) -> None:
        with self._guard:
            keys = [
                key
                for key, state in self.server_run.plans.items()
                if isinstance(key, tuple)
                and len(key) == 2
                and key[1] == board_id
                and isinstance(state, _PlanState)
            ]
            for key in keys:
        )

    return pending


class SetupWorkflow:
    """Own setup attempts, paired setup/fix allowances, and immutable reports.

    This object is intentionally run-scoped. Durable reports contain evidence but
    never restore an allowance, permission, assignment, or unlocked tool.
    """

    def __init__(
        self,
        reports: ReportWriter,
        inventory_provider: InventoryProvider,
        *,
        preflight: PreflightEngine | None = None,
        phase_handlers: Mapping[SetupPhase, SetupPhaseHandler] | None = None,
        on_allowance_closed: AllowanceClosed | None = None,
        on_cache_confirmation: CacheConfirmationHandler | None = None,
        cancellation_checkpoint: CancellationCheckpoint | None = None,
    ) -> None:
        self.reports = reports
        self.inventory_provider = inventory_provider
        self.preflight = preflight or PreflightEngine()
        supplied = dict(phase_handlers or {})
        self.phase_handlers = {
            phase: supplied.get(phase, _default_phase_handler(phase))
            for phase in PHASE_ORDER
            if phase
            not in {
                SetupPhase.INPUT,
                SetupPhase.PREFLIGHT,
                SetupPhase.SELECTION,
                SetupPhase.TARGET_RESOLUTION,
            }
        }
        self.on_allowance_closed = on_allowance_closed or (lambda board_id, reason: None)
        self.on_cache_confirmation = on_cache_confirmation or (lambda user_input, decision: None)
        self.cancellation_checkpoint = cancellation_checkpoint or (lambda: None)
        self._allowances: dict[str, _SetupAllowance] = {}
        self._current_allowance_by_board: dict[str, str] = {}
        self._states: dict[str, _SetupState] = {}
        self._continuation_by_allowance: dict[str, str] = {}
        self._guard = threading.RLock()

    def begin_plan(
        self,
        allowance_id: str,
        user_input: SetupUserInput,
        *,
        mode: SetupMode,
    ) -> None:
        """Register one externally validated board_setup plan allowance."""

        if mode not in {"setup", "repair"}:
            raise SetupWorkflowError("mode must be setup or repair")
        normalized_id = allowance_id.strip()
        if not normalized_id:
            raise SetupWorkflowError("allowance_id must be non-empty")
        with self._guard:
            if normalized_id in self._allowances:
                raise SetupWorkflowError(f"Setup allowance '{normalized_id}' already exists")
            previous_id = self._current_allowance_by_board.get(user_input.board_id)
            if previous_id is not None:
                self._close_allowance_locked(previous_id, "replaced by a new setup plan")
            self._allowances[normalized_id] = _SetupAllowance(
                normalized_id,
                user_input.board_id,
                user_input.connection_id,
                mode,
            )
            self._current_allowance_by_board[user_input.board_id] = normalized_id

        if allowance is None:
            raise SetupWorkflowError(f"Unknown setup allowance '{allowance_id}'")
        if allowance.closed:
            raise SetupWorkflowError(
                f"Setup allowance '{allowance_id}' is closed: {allowance.close_reason}"
            )
        return allowance

    def _close_allowance_locked(self, allowance_id: str, reason: str) -> None:
        allowance = self._allowances.get(allowance_id)
        if allowance is None or allowance.closed:
            return
        allowance.closed = True
        allowance.close_reason = reason
        if self._current_allowance_by_board.get(allowance.board_id) == allowance_id:
            self._current_allowance_by_board.pop(allowance.board_id, None)
        self.on_allowance_closed(allowance.board_id, reason)


